/* Reset and base */
* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.app {
  background: #16213e;
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: #e94560;
  text-align: center;
  letter-spacing: 1px;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

#todo-input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid #0f3460;
  border-radius: 8px;
  background: #1a1a2e;
  color: #e0e0e0;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
}

#todo-input:focus {
  border-color: #e94560;
}

#todo-add {
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  background: #e94560;
  color: #fff;
  font-size: 1.25rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

#todo-add:hover { background: #c73650; }
#todo-add:active { transform: scale(0.95); }
#todo-add:focus-visible { outline: 3px solid #e94560; outline-offset: 2px; }

.counts {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  color: #a0a0b0;
  margin-bottom: 16px;
  padding: 0 4px;
}

.counts span { font-weight: 600; }

#todo-total, #remaining { color: #e94560; }

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: #1a1a2e;
  border-radius: 8px;
  border: 2px solid #0f3460;
  transition: border-color 0.2s;
}

.todo-item:hover { border-color: #e94560; }

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
  flex-shrink: 0;
}

.todo-item .task-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}

.todo-item .task-text.completed {
  text-decoration: line-through;
  color: #6a6a7a;
}

.todo-item .delete-btn {
  background: none;
  border: none;
  color: #e94560;
  font-size: 1.25rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: background 0.2s, color 0.2s;
}

.todo-item .delete-btn:hover {
  background: #e94560;
  color: #fff;
}

.todo-item .delete-btn:active { transform: scale(0.9); }
.todo-item .delete-btn:focus-visible { outline: 3px solid #e94560; outline-offset: 2px; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

@media (max-width: 400px) {
  .app { padding: 16px; }
  h1 { font-size: 1.25rem; }
  #todo-input { padding: 10px 12px; }
  #todo-add { padding: 10px 16px; }
}

let nextId = 1;
const tasks = [];

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.completed).length;
}

function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'todo-item';

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.checked = task.completed;
  checkbox.id = `todo-check-${task.id}`;
  checkbox.setAttribute('aria-label', `Mark task ${task.id} as ${task.completed ? 'incomplete' : 'complete'}`);

  const span = document.createElement('span');
  span.className = 'task-text';
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;
  if (task.completed) span.classList.add('completed');

  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'delete-btn';
  deleteBtn.id = `todo-delete-${task.id}`;
  deleteBtn.setAttribute('aria-label', `Delete task ${task.id}`);
  deleteBtn.textContent = '×';

  checkbox.addEventListener('change', () => {
    task.completed = checkbox.checked;
    span.classList.toggle('completed', task.completed);
    checkbox.setAttribute('aria-label', `Mark task ${task.id} as ${task.completed ? 'incomplete' : 'complete'}`);
    updateCounts();
  });

  deleteBtn.addEventListener('click', () => {
    const index = tasks.indexOf(task);
    if (index > -1) tasks.splice(index, 1);
    li.remove();
    updateCounts();
  });

  li.appendChild(checkbox);
  li.appendChild(span);
  li.appendChild(deleteBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, completed: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  updateCounts();
  input.focus();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addTask();
});

updateCounts();
